public static class FireKingdomBuilder {
 const string Root="Assets/ReinoDeFuego/";const string Art=Root+"0_3_Art/";const string Heroes="Assets/Prototype_CoopBeam/0_2_Prefabs/";
 static Material mat;static Sprite tile,spark;static EnemyBase[] prefabs;static Sprite[] backgrounds;
 public static readonly string[] Titles={"HUERTO DE BRASAS","PUERTO DE FUNDICION","GRUTAS DEL MAGMA CANTOR","BASTION DE LA CENIZA","CORAZON DE BRONTOFORNO"};
 static readonly string[] Lessons={"Los hornos avisan antes de lanzar sus brasas.\nCada baja deja botin: salten o crucen el lazo.","Las cintas y el ascensor cambian su posicion.\nLas marcas cian avisan antes del fuego.","Los fenix disparan plumas en abanico.\nCristales elasticos abren rutas de escape.","El basalto se rompe; los respiraderos se alternan.\nEsquiven al escarabajo y ataquen al descansar.","Brontoforno protege su corazon de magma.\nUsen las galerias y los huecos de sus ataques.\nNucleo abierto: crucen el lazo y la Resonancia."};
 [MenuItem("Coop Beam/Expansion/Build Fire Kingdom Only")]
 public static void Build(){if(EditorApplication.isPlaying)throw new Exception("Exit Play first");var original=UnityEngine.SceneManagement.SceneManager.GetActiveScene();if(original.isDirty)throw new Exception("Unsaved scene: save manually before building");string originalPath=original.path;
  foreach(var path in Enumerable.Range(1,5).Select(n=>CandyCampaign.ScenePath(n,2)))if(File.Exists(path))throw new Exception("Fire scenes already exist. Builder never overwrites existing levels: "+path);
  mat=AssetDatabase.LoadAssetAtPath<Material>("Assets/Prototype_CoopBeam/0_3_Art/SpriteUnlit.mat");spark=AssetDatabase.LoadAssetAtPath<Sprite>("Assets/ReinoDeChicle/0_3_Art/PixelArt/Tiles/PixelSpark.png");if(!spark)spark=AssetDatabase.LoadAssetAtPath<Sprite>("Assets/Prototype_CoopBeam/0_3_Art/mote.png");tile=MakeTile();backgrounds=Backgrounds();
  prefabs=new EnemyBase[7];for(int i=0;i<6;i++)prefabs[i]=MakeEnemy(i);prefabs[6]=MakeBoss();
  for(int n=1;n<=5;n++)BuildScene(n);
  var builds=EditorBuildSettings.scenes.ToList();for(int n=1;n<=5;n++){string path=CandyCampaign.ScenePath(n,2);if(!builds.Any(s=>s.path==path))builds.Add(new EditorBuildSettingsScene(path,true));}EditorBuildSettings.scenes=builds.ToArray();AssetDatabase.SaveAssets();if(!string.IsNullOrEmpty(originalPath))EditorSceneManager.OpenScene(originalPath);Debug.Log("FIRE_KINGDOM_BUILT: five new scenes, six enemies, Brontoforno; existing candy scenes untouched.");
 }
 static Texture2D Import(string path,bool readable=true){AssetDatabase.ImportAsset(path,ImportAssetOptions.ForceSynchronousImport);var imp=(TextureImporter)AssetImporter.GetAtPath(path);imp.textureType=TextureImporterType.Default;imp.isReadable=readable;imp.filterMode=FilterMode.Point;imp.mipmapEnabled=false;imp.textureCompression=TextureImporterCompression.Uncompressed;imp.alphaIsTransparency=true;imp.npotScale=TextureImporterNPOTScale.None;imp.maxTextureSize=4096;imp.SaveAndReimport();return AssetDatabase.LoadAssetAtPath<Texture2D>(path);}
 static Sprite[] Frames(string file,string name,int cols,int rows,int row,int count,float height){var texture=Import(Art+file);string path=Art+name+".asset";var set=ScriptableObject.CreateInstance<PixelAnimationSet>();AssetDatabase.CreateAsset(set,path);set.frames=new Sprite[count];int w=texture.width/cols,h=texture.height/rows;float ppu=1;
  for(int f=0;f<count;f++){int cx=f%cols,cy=rows-1-(row+f/cols);int x=cx*w,y=cy*h;if(file=="FireEnemies.png"){int[] cuts={0,187,354,526,699,888,1086};int top=Mathf.RoundToInt(cuts[row]/1086f*texture.height),bottom=Mathf.RoundToInt(cuts[row+1]/1086f*texture.height);y=texture.height-bottom;h=bottom-top;}int minX=w,minY=h,maxX=0,maxY=0;for(int yy=0;yy<h;yy++)for(int xx=0;xx<w;xx++)if(texture.GetPixel(x+xx,y+yy).a>.35f){minX=Mathf.Min(minX,xx);maxX=Mathf.Max(maxX,xx);minY=Mathf.Min(minY,yy);maxY=Mathf.Max(maxY,yy);}if(maxY<=minY)throw new Exception("Empty sprite cell "+name+" "+f);if(f==0)ppu=(maxY-minY+1)/height;
   var frame=Sprite.Create(texture,new Rect(x,y,w,h),new Vector2((minX+maxX)*.5f/w,(float)minY/h),ppu,0,SpriteMeshType.FullRect);frame.name=name+"_"+f.ToString("00");AssetDatabase.AddObjectToAsset(frame,set);set.frames[f]=frame;
  }EditorUtility.SetDirty(set);return set.frames;
 }
 static Sprite[] Backgrounds(){var texture=Import(Art+"FireBackgrounds.png",false);var set=ScriptableObject.CreateInstance<PixelAnimationSet>();AssetDatabase.CreateAsset(set,Art+"FireBackdrops.asset");set.frames=new Sprite[5];int[] cuts={0,256,568,864,1184,1536};for(int i=0;i<5;i++){float top=cuts[i]/1536f*texture.height,bottom=cuts[i+1]/1536f*texture.height;var sprite=Sprite.Create(texture,new Rect(0,texture.height-bottom,texture.width,bottom-top),Vector2.one*.5f,32,0,SpriteMeshType.FullRect);sprite.name=Titles[i];AssetDatabase.AddObjectToAsset(sprite,set);set.frames[i]=sprite;}EditorUtility.SetDirty(set);return set.frames;}
 static Sprite[] tileFrames;
 static Sprite MakeTile(){tileFrames=new Sprite[4];for(int frame=0;frame<4;frame++){var t=new Texture2D(64,16,TextureFormat.RGBA32,false);for(int y=0;y<16;y++)for(int x=0;x<64;x++){Color c=y>12?new Color(.95f,.63f,.2f):y>9?new Color(.38f,.22f,.23f):new Color(.12f,.10f,.19f);if(y<10&&(x+y*2)%19<2)c=new Color(.45f,.15f,.16f);if(y==11&&(x+frame*3)%16<4)c=new Color(1,.82f,.25f);if(y==0)c=new Color(.07f,.05f,.12f);t.SetPixel(x,y,c);}t.Apply();string path=Art+"ForgeTile_"+frame+".png";File.WriteAllBytes(path,t.EncodeToPNG());UnityEngine.Object.DestroyImmediate(t);AssetDatabase.ImportAsset(path);var imp=(TextureImporter)AssetImporter.GetAtPath(path);imp.textureType=TextureImporterType.Sprite;imp.spritePixelsPerUnit=32;imp.filterMode=FilterMode.Point;imp.mipmapEnabled=false;imp.textureCompression=TextureImporterCompression.Uncompressed;imp.SaveAndReimport();tileFrames[frame]=AssetDatabase.LoadAssetAtPath<Sprite>(path);}return tileFrames[0];}
 static GameObject Visual(string name,Sprite sprite,Transform parent,Vector2 point,int order){var g=new GameObject(name);if(parent)g.transform.SetParent(parent,false);g.transform.localPosition=point;var r=g.AddComponent<SpriteRenderer>();r.sprite=sprite;r.sharedMaterial=mat;r.sortingOrder=order;return g;}
 static EnemyBase MakeEnemy(int index){string[] names={"KilnGrenadier","BasaltBeetle","SparkSalamander","EmberPhoenix","FireworkFlower","FuseImp"};float[] heights={1.35f,1.8f,1.15f,1.4f,1.5f,1.1f};var frames=Frames("FireEnemies.png",names[index],8,6,index,8,heights[index]);var g=new GameObject(names[index]);g.layer=10;var body=g.AddComponent<Rigidbody2D>();body.bodyType=index==3||index==4?RigidbodyType2D.Kinematic:RigidbodyType2D.Dynamic;body.gravityScale=3;body.freezeRotation=true;body.useFullKinematicContacts=true;body.collisionDetectionMode=CollisionDetectionMode2D.Continuous;body.interpolation=RigidbodyInterpolation2D.Interpolate;
  var col=g.AddComponent<CapsuleCollider2D>();col.size=new Vector2(index==1?1.25f:.85f,index==1?1.5f:1);var visual=Visual("Pixel art",frames[0],g.transform,Vector2.down*col.size.y*.5f,4);var e=g.AddComponent<EnemyBase>();e.kind=index==3?EnemyKind.Flyer:index==4?EnemyKind.Cannon:index==1?EnemyKind.Armored:index==5?EnemyKind.Jumper:EnemyKind.Walker;e.maxHealth=new[]{52f,95,46,50,72,42}[index];e.speed=1;e.sprite=visual.GetComponent<SpriteRenderer>();e.visual=visual.transform;var ai=g.AddComponent<FireEnemyBrain>();ai.role=(FireEnemyBrain.Role)index;ai.interval=4.5f;var animation=visual.AddComponent<FireSpriteAnimator>();animation.frames=frames;visual.AddComponent<PixelActorVisual>();g.AddComponent<ActorPhysics2D>();var p=PrefabUtility.SaveAsPrefabAsset(g,Root+"0_2_Prefabs/"+names[index]+".prefab");UnityEngine.Object.DestroyImmediate(g);return p.GetComponent<EnemyBase>();
 }
 static EnemyBase MakeBoss(){var frames=Frames("Brontoforno.png","Brontoforno",4,4,0,16,4.2f);var g=new GameObject("Brontoforno");g.layer=12;var body=g.AddComponent<Rigidbody2D>();body.bodyType=RigidbodyType2D.Kinematic;body.useFullKinematicContacts=true;var col=g.AddComponent<BoxCollider2D>();col.size=new Vector2(2.6f,3.2f);var visual=Visual("Living foundry",frames[0],g.transform,Vector2.down*1.6f,4);var enemy=g.AddComponent<EnemyBase>();enemy.kind=EnemyKind.Boss;enemy.maxHealth=1600;enemy.sprite=visual.GetComponent<SpriteRenderer>();enemy.visual=visual.transform;var king=g.AddComponent<FireForgeBoss>();var core=new GameObject("Magma heart - ray target");core.layer=10;core.transform.SetParent(g.transform,false);core.transform.localPosition=Vector3.up*.3f;var c=core.AddComponent<CircleCollider2D>();c.isTrigger=true;c.radius=.6f;king.core=c;var light=Visual("Exposed magma",spark,g.transform,Vector2.up*.3f,6);light.transform.localScale=Vector3.one*.7f;king.coreArt=light.GetComponent<SpriteRenderer>();var animation=visual.AddComponent<FireSpriteAnimator>();animation.frames=frames;animation.boss=true;var p=PrefabUtility.SaveAsPrefabAsset(g,Root+"0_2_Prefabs/Brontoforno.prefab");UnityEngine.Object.DestroyImmediate(g);return p.GetComponent<EnemyBase>();}
 static GameObject Platform(string name,Vector2 point,Vector2 size,bool semi=true,int mode=-1){var g=new GameObject(name);g.transform.position=point;g.layer=semi?9:8;var col=g.AddComponent<BoxCollider2D>();col.size=size;if(semi){col.usedByEffector=true;var eff=g.AddComponent<PlatformEffector2D>();eff.useOneWay=true;eff.useOneWayGrouping=true;eff.surfaceArc=165;}var v=Visual("Obsidian and forge lights",tile,g.transform,Vector2.zero,0);v.transform.localScale=new Vector3(size.x/tile.bounds.size.x,size.y/tile.bounds.size.y,1);var shimmer=v.AddComponent<PixelSurfaceAnimator>();shimmer.frames=tileFrames;shimmer.framesPerSecond=4;if(mode>=0){var env=g.AddComponent<CandyEnvironment>();env.kind=(CandySurfaceKind)mode;env.art=v.transform;env.strength=mode==0?16:1.4f;if(mode==2){var rb=g.AddComponent<Rigidbody2D>();rb.bodyType=RigidbodyType2D.Kinematic;env.travel=1.6f;env.period=5;}}return g;}
 static void BuildScene(int number){var scene=EditorSceneManager.NewScene(NewSceneSetup.EmptyScene,NewSceneMode.Single);var cam=new GameObject("Forge pixel camera",typeof(Camera),typeof(AudioListener)).GetComponent<Camera>();cam.tag="MainCamera";cam.orthographic=true;cam.orthographicSize=7.5f;cam.transform.position=new Vector3(0,1,-10);cam.backgroundColor=new Color(.13f,.065f,.13f);cam.gameObject.AddComponent<ArenaCamera>();cam.gameObject.AddComponent<PixelViewport>();var bg=Visual("Volcanic backdrop",backgrounds[number-1],null,new Vector2(0,1),-30);bg.transform.localScale=new Vector3(26/backgrounds[number-1].bounds.size.x,15/backgrounds[number-1].bounds.size.y,1);bg.GetComponent<SpriteRenderer>().color=new Color(.72f,.64f,.68f);
  Platform("Obsidian foundation",new Vector2(0,-4.7f),new Vector2(23,.8f),false);
  if(number==1){Platform("Ember grove west",new Vector2(-6,-2.2f),new Vector2(4.5f,.45f));Platform("Ember grove east",new Vector2(6,-2f),new Vector2(3.5f,.45f));Platform("Hanging basalt",new Vector2(0,.2f),new Vector2(4,.45f));}
  if(number==2){Platform("Forge belt eastbound",new Vector2(-6,-2.1f),new Vector2(4.5f,.5f),true,1);var east=Platform("Forge belt westbound",new Vector2(6,-2.1f),new Vector2(4.5f,.5f),true,1);east.GetComponent<CandyEnvironment>().strength=-1.6f;var lift=Platform("Bellows lift",new Vector2(0,.3f),new Vector2(3.5f,.5f),true,2);lift.GetComponent<CandyEnvironment>().moveAxis=Vector2.up;Platform("Crane west",new Vector2(-6,2.6f),new Vector2(3.5f,.45f));Platform("Crane east",new Vector2(6,2.6f),new Vector2(3.5f,.45f));}
  if(number==3){Platform("Elastic geode west",new Vector2(-7,-2.1f),new Vector2(3.5f,.5f),true,0);Platform("Elastic geode east",new Vector2(7,-2.1f),new Vector2(3.5f,.5f),true,0);Platform("Basalt step west",new Vector2(-4,-.3f),new Vector2(3,.45f));Platform("Basalt step east",new Vector2(4,-.3f),new Vector2(3,.45f));Platform("Singing geode",new Vector2(0,2.1f),new Vector2(4,.45f));}
  if(number==4){Platform("Brittle basalt west",new Vector2(-6,-2.1f),new Vector2(4.5f,.5f),true,3);Platform("Brittle basalt east",new Vector2(6,-2.1f),new Vector2(4.5f,.5f),true,3);Platform("Swinging iron bridge",new Vector2(0,.4f),new Vector2(4,.5f),true,2);Platform("Ash refuge west",new Vector2(-6,2.6f),new Vector2(3.5f,.45f));Platform("Ash refuge east",new Vector2(6,2.6f),new Vector2(3.5f,.45f));}
  if(number==5){Platform("Forge gallery west",new Vector2(-6,-1.95f),new Vector2(4,.45f));Platform("Forge gallery east",new Vector2(6,-1.95f),new Vector2(4,.45f));Platform("Sun wheel west",new Vector2(-5,.6f),new Vector2(3.5f,.45f));Platform("Sun wheel east",new Vector2(5,.6f),new Vector2(3.5f,.45f));}
  foreach(float x in new[]{-11.7f,11.7f}){var wall=new GameObject("Basalt boundary");wall.layer=8;wall.transform.position=new Vector2(x,1);wall.AddComponent<BoxCollider2D>().size=new Vector2(.5f,13);}
  var game=new GameObject("Fire encounter "+number).AddComponent<GameManager>();game.level=Definition(number);game.enemyPrefabs=prefabs;game.particle=spark;game.players=new PlayerHealth[2];for(int i=0;i<2;i++){var hero=(GameObject)PrefabUtility.InstantiatePrefab(AssetDatabase.LoadAssetAtPath<GameObject>(Heroes+(i==0?"Coral":"Celeste")+".prefab"));hero.transform.position=new Vector2(i==0?-6:6,-3.7f);hero.name=i==0?"Mora":"Lima";game.players[i]=hero.GetComponent<PlayerHealth>();game.players[i].spawn=hero.transform.position;PrefabUtility.RecordPrefabInstancePropertyModifications(game.players[i]);PrefabUtility.RecordPrefabInstancePropertyModifications(hero.transform);}
  var beam=new GameObject("Cooperative link").AddComponent<CoopBeam.CoopBeam>();beam.red=game.players[0];beam.blue=game.players[1];beam.core=Line(beam.transform,"Core",.055f,7);beam.halo=Line(beam.transform,"Halo",.24f,6);beam.outline=Line(beam.transform,"Outline",.13f,5);beam.outline.startColor=beam.outline.endColor=new Color(.08f,.08f,.2f);var exit=game.gameObject.AddComponent<CandyLevelExit>();exit.game=game;var hud=new GameObject("Fire HUD").AddComponent<CandyPixelHUD>();hud.game=game;hud.exit=exit;new GameObject("Emberfall").AddComponent<FireAtmosphere>().level=number;new GameObject("Announced furnace vents").AddComponent<FireArenaRhythm>().level=number;EditorSceneManager.SaveScene(scene,CandyCampaign.ScenePath(number,2));
 }
 static LineRenderer Line(Transform parent,string name,float width,int order){var g=new GameObject(name);g.transform.SetParent(parent);var r=g.AddComponent<LineRenderer>();r.sharedMaterial=mat;r.positionCount=2;r.useWorldSpace=true;r.widthMultiplier=width;r.sortingOrder=order;return r;}
 static CandyLevelDefinition Definition(int n){var d=ScriptableObject.CreateInstance<CandyLevelDefinition>();d.number=n;d.fireKingdom=true;d.title=Titles[n-1];d.lesson=Lessons[n-1];d.boss=n==5;int[][] waves=n==1?new[]{new[]{0,2},new[]{0,5,2},new[]{1,0,2}}:n==2?new[]{new[]{0,5,4},new[]{1,3,0},new[]{1,4,5,3}}:n==3?new[]{new[]{2,3,4},new[]{0,3,5,4},new[]{1,4,3,2}}:n==4?new[]{new[]{1,3,4},new[]{2,5,0,3},new[]{1,4,5,3,2}}:new[]{new[]{0,5,2},new[]{1,3,4},new[]{6}};d.waves=new CandyWave[3];for(int w=0;w<3;w++){d.waves[w]=new CandyWave{enemyTypes=waves[w],spawnPositions=new Vector2[waves[w].Length]};for(int i=0;i<waves[w].Length;i++){int k=waves[w][i];float x=waves[w].Length==1?0:(i-(waves[w].Length-1)*.5f)*4;float y=k==3?2.8f:k==6?-2.65f:-3.65f;if(k==0&&w>=1&&n<5){x=n==3?-4:-6;y=n==3?.425f:n==1?-1.475f:-1.35f;}if(k==4){x=n==3?0:n==5?5:6;y=n==3?2.825f:n==5?1.325f:3.325f;}d.waves[w].spawnPositions[i]=new Vector2(x,y);}}AssetDatabase.CreateAsset(d,Root+"0_7_LevelData/Fire_Level_0"+n+".asset");return d;}
}
